use anchor_lang::prelude::*;

use crate::{EvidenceRequirement, WorkOrder, AEROSETTLE_PROTOCOL_VERSION, MAX_BASIS_POINTS};

/// Evidence generated by a physical/edge agent while executing work.
///
/// Large artifacts such as telemetry, images, video and sensor datasets
/// remain off-chain. AeroSettle stores deterministic cryptographic
/// commitments to those artifacts.
#[derive(AnchorSerialize, AnchorDeserialize, Clone, Debug, PartialEq, Eq)]
pub struct EvidenceManifest {
    pub protocol_version: u8,

    /// WorkOrder this evidence belongs to.
    pub work_order_id: [u8; 32],

    /// PhysicalAgent that generated the evidence.
    pub agent_id: [u8; 32],

    /// Bitmask of EvidenceRequirement values actually provided.
    pub provided_evidence: u64,

    pub telemetry_hash: [u8; 32],
    pub gps_trace_hash: [u8; 32],
    pub image_manifest_hash: [u8; 32],
    pub video_manifest_hash: [u8; 32],
    pub sensor_readings_hash: [u8; 32],
    pub ai_inference_hash: [u8; 32],

    /// Merkle root or aggregate commitment of all external artifacts.
    ///
    /// Protocol v1 does not mandate the tree construction yet.
    /// That canonicalization will be defined separately.
    pub artifact_root: [u8; 32],
}

impl EvidenceManifest {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        work_order_id: [u8; 32],
        agent_id: [u8; 32],
        provided_evidence: u64,
        telemetry_hash: [u8; 32],
        gps_trace_hash: [u8; 32],
        image_manifest_hash: [u8; 32],
        video_manifest_hash: [u8; 32],
        sensor_readings_hash: [u8; 32],
        ai_inference_hash: [u8; 32],
        artifact_root: [u8; 32],
    ) -> Self {
        Self {
            protocol_version: AEROSETTLE_PROTOCOL_VERSION,
            work_order_id,
            agent_id,
            provided_evidence,
            telemetry_hash,
            gps_trace_hash,
            image_manifest_hash,
            video_manifest_hash,
            sensor_readings_hash,
            ai_inference_hash,
            artifact_root,
        }
    }

    pub const fn contains(&self, requirement: EvidenceRequirement) -> bool {
        self.provided_evidence & requirement.bit() != 0
    }

    pub const fn satisfies(&self, required_evidence: u64) -> bool {
        self.provided_evidence & required_evidence == required_evidence
    }

    pub fn is_complete_for(&self, work_order: &WorkOrder) -> bool {
        self.protocol_version == work_order.protocol_version
            && self.work_order_id == work_order.work_order_id
            && self.satisfies(work_order.evidence_requirements)
    }
}

/// Immutable receipt describing one execution of a WorkOrder.
///
/// This binds:
///
/// WorkOrder -> PhysicalAgent -> execution interval -> evidence commitment.
#[derive(AnchorSerialize, AnchorDeserialize, Clone, Debug, PartialEq, Eq)]
pub struct ExecutionReceipt {
    pub protocol_version: u8,

    pub work_order_id: [u8; 32],
    pub agent_id: [u8; 32],

    /// Unix timestamp when physical execution started.
    pub started_at: i64,

    /// Unix timestamp when physical execution finished.
    pub ended_at: i64,

    /// SHA-256 commitment of the canonical serialized EvidenceManifest.
    pub evidence_manifest_hash: [u8; 32],

    /// Software/firmware commitment used during execution.
    pub software_hash: [u8; 32],

    /// AI/model manifest commitment.
    ///
    /// Zero may be used when no AI model participated.
    pub model_manifest_hash: [u8; 32],
}

impl ExecutionReceipt {
    pub fn new(
        work_order_id: [u8; 32],
        agent_id: [u8; 32],
        started_at: i64,
        ended_at: i64,
        evidence_manifest_hash: [u8; 32],
        software_hash: [u8; 32],
        model_manifest_hash: [u8; 32],
    ) -> Self {
        Self {
            protocol_version: AEROSETTLE_PROTOCOL_VERSION,
            work_order_id,
            agent_id,
            started_at,
            ended_at,
            evidence_manifest_hash,
            software_hash,
            model_manifest_hash,
        }
    }

    pub fn duration_seconds(&self) -> Option<u64> {
        let duration = self.ended_at.checked_sub(self.started_at)?;

        u64::try_from(duration).ok()
    }

    pub const fn has_valid_time_range(&self) -> bool {
        self.started_at <= self.ended_at
    }

    pub fn is_valid_for(&self, work_order: &WorkOrder) -> bool {
        self.protocol_version == work_order.protocol_version
            && self.work_order_id == work_order.work_order_id
            && self.has_valid_time_range()
            && self.ended_at <= work_order.execution_deadline
    }
}

/// Final interpretation produced by an authorized verifier.
#[derive(AnchorSerialize, AnchorDeserialize, Clone, Copy, Debug, PartialEq, Eq)]
pub enum VerificationStatus {
    Accepted,
    Rejected,
}

/// Verifier commitment used later by the settlement instruction.
///
/// The transaction submitting this structure will ultimately require
/// authorization from `verifier`.
#[derive(AnchorSerialize, AnchorDeserialize, Clone, Debug, PartialEq, Eq)]
pub struct VerificationAttestation {
    pub protocol_version: u8,

    pub work_order_id: [u8; 32],

    /// SHA-256 commitment of the canonical ExecutionReceipt.
    pub receipt_hash: [u8; 32],

    /// Must match ExecutionReceipt.evidence_manifest_hash.
    pub evidence_manifest_hash: [u8; 32],

    pub verifier: Pubkey,

    pub status: VerificationStatus,

    /// Verified completion from 0 to 10_000 basis points.
    pub completion_bps: u16,

    /// Unix timestamp at which verification was issued.
    pub verified_at: i64,
}

impl VerificationAttestation {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        work_order_id: [u8; 32],
        receipt_hash: [u8; 32],
        evidence_manifest_hash: [u8; 32],
        verifier: Pubkey,
        status: VerificationStatus,
        completion_bps: u16,
        verified_at: i64,
    ) -> Self {
        Self {
            protocol_version: AEROSETTLE_PROTOCOL_VERSION,
            work_order_id,
            receipt_hash,
            evidence_manifest_hash,
            verifier,
            status,
            completion_bps,
            verified_at,
        }
    }

    pub const fn has_valid_completion(&self) -> bool {
        if self.completion_bps > MAX_BASIS_POINTS {
            return false;
        }

        match self.status {
            VerificationStatus::Accepted => true,

            VerificationStatus::Rejected => self.completion_bps == 0,
        }
    }

    pub fn is_valid_for(&self, work_order: &WorkOrder, receipt: &ExecutionReceipt) -> bool {
        self.protocol_version == work_order.protocol_version
            && self.work_order_id == work_order.work_order_id
            && receipt.work_order_id == work_order.work_order_id
            && receipt.evidence_manifest_hash == self.evidence_manifest_hash
            && self.verifier == work_order.settlement.verifier
            && self.has_valid_completion()
            && self.verified_at >= receipt.ended_at
            && self.verified_at <= work_order.verification_deadline
            && receipt.is_valid_for(work_order)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    use crate::{
        AgentType, Capability, EvidenceRequirement, PaymentModel, PhysicalAgent, SettlementTerms,
        WorkType,
    };

    fn drone() -> PhysicalAgent {
        PhysicalAgent::new(
            [1u8; 32],
            Pubkey::new_unique(),
            AgentType::Drone,
            Capability::AerialMobility.bit()
                | Capability::ThermalVision.bit()
                | Capability::Gps.bit()
                | Capability::Telemetry.bit(),
            [2u8; 32],
        )
    }

    fn work_order() -> WorkOrder {
        WorkOrder::new(
            [3u8; 32],
            Pubkey::new_unique(),
            WorkType::Inspection,
            Capability::AerialMobility.bit()
                | Capability::ThermalVision.bit()
                | Capability::Gps.bit(),
            EvidenceRequirement::Telemetry.bit()
                | EvidenceRequirement::GpsTrace.bit()
                | EvidenceRequirement::ImageManifest.bit()
                | EvidenceRequirement::DeviceSignature.bit(),
            [4u8; 32],
            SettlementTerms {
                token_mint: Pubkey::new_unique(),
                total_amount: 100_000_000,
                payment_model: PaymentModel::Proportional,
                verifier: Pubkey::new_unique(),
            },
            1_000,
            1_300,
        )
    }

    fn evidence(order: &WorkOrder) -> EvidenceManifest {
        EvidenceManifest::new(
            order.work_order_id,
            drone().agent_id,
            EvidenceRequirement::Telemetry.bit()
                | EvidenceRequirement::GpsTrace.bit()
                | EvidenceRequirement::ImageManifest.bit()
                | EvidenceRequirement::DeviceSignature.bit(),
            [10u8; 32],
            [11u8; 32],
            [12u8; 32],
            [0u8; 32],
            [0u8; 32],
            [0u8; 32],
            [13u8; 32],
        )
    }

    fn receipt(order: &WorkOrder) -> ExecutionReceipt {
        ExecutionReceipt::new(
            order.work_order_id,
            [1u8; 32],
            800,
            950,
            [20u8; 32],
            [21u8; 32],
            [22u8; 32],
        )
    }

    #[test]
    fn evidence_manifest_satisfies_work_order() {
        let order = work_order();
        let manifest = evidence(&order);

        assert!(manifest.is_complete_for(&order));

        assert!(manifest.contains(EvidenceRequirement::Telemetry));

        assert!(manifest.contains(EvidenceRequirement::DeviceSignature));
    }

    #[test]
    fn missing_evidence_fails_requirement_check() {
        let order = work_order();

        let manifest = EvidenceManifest::new(
            order.work_order_id,
            [1u8; 32],
            EvidenceRequirement::Telemetry.bit() | EvidenceRequirement::GpsTrace.bit(),
            [10u8; 32],
            [11u8; 32],
            [0u8; 32],
            [0u8; 32],
            [0u8; 32],
            [0u8; 32],
            [13u8; 32],
        );

        assert!(!manifest.is_complete_for(&order));
    }

    #[test]
    fn evidence_from_other_work_order_is_invalid() {
        let order = work_order();
        let mut manifest = evidence(&order);

        manifest.work_order_id = [99u8; 32];

        assert!(!manifest.is_complete_for(&order));
    }

    #[test]
    fn execution_receipt_has_valid_duration() {
        let order = work_order();
        let receipt = receipt(&order);

        assert_eq!(receipt.duration_seconds(), Some(150));

        assert!(receipt.is_valid_for(&order));
    }

    #[test]
    fn execution_receipt_rejects_inverted_time() {
        let order = work_order();

        let receipt = ExecutionReceipt::new(
            order.work_order_id,
            [1u8; 32],
            950,
            900,
            [20u8; 32],
            [21u8; 32],
            [22u8; 32],
        );

        assert_eq!(receipt.duration_seconds(), None);
        assert!(!receipt.is_valid_for(&order));
    }

    #[test]
    fn execution_after_deadline_is_invalid() {
        let order = work_order();

        let receipt = ExecutionReceipt::new(
            order.work_order_id,
            [1u8; 32],
            900,
            1_001,
            [20u8; 32],
            [21u8; 32],
            [22u8; 32],
        );

        assert!(!receipt.is_valid_for(&order));
    }

    #[test]
    fn valid_partial_attestation_is_accepted() {
        let order = work_order();
        let receipt = receipt(&order);

        let attestation = VerificationAttestation::new(
            order.work_order_id,
            [30u8; 32],
            receipt.evidence_manifest_hash,
            order.settlement.verifier,
            VerificationStatus::Accepted,
            7_350,
            1_100,
        );

        assert!(attestation.is_valid_for(&order, &receipt));

        let (payout, refund) = order
            .settlement
            .calculate_payout(attestation.completion_bps)
            .unwrap();

        assert_eq!(payout, 73_500_000);
        assert_eq!(refund, 26_500_000);
    }

    #[test]
    fn wrong_verifier_is_rejected() {
        let order = work_order();
        let receipt = receipt(&order);

        let attestation = VerificationAttestation::new(
            order.work_order_id,
            [30u8; 32],
            receipt.evidence_manifest_hash,
            Pubkey::new_unique(),
            VerificationStatus::Accepted,
            10_000,
            1_100,
        );

        assert!(!attestation.is_valid_for(&order, &receipt));
    }

    #[test]
    fn verification_after_deadline_is_rejected() {
        let order = work_order();
        let receipt = receipt(&order);

        let attestation = VerificationAttestation::new(
            order.work_order_id,
            [30u8; 32],
            receipt.evidence_manifest_hash,
            order.settlement.verifier,
            VerificationStatus::Accepted,
            10_000,
            1_301,
        );

        assert!(!attestation.is_valid_for(&order, &receipt));
    }

    #[test]
    fn verification_before_execution_end_is_rejected() {
        let order = work_order();
        let receipt = receipt(&order);

        let attestation = VerificationAttestation::new(
            order.work_order_id,
            [30u8; 32],
            receipt.evidence_manifest_hash,
            order.settlement.verifier,
            VerificationStatus::Accepted,
            10_000,
            949,
        );

        assert!(!attestation.is_valid_for(&order, &receipt));
    }

    #[test]
    fn rejected_attestation_must_have_zero_completion() {
        let order = work_order();
        let receipt = receipt(&order);

        let invalid = VerificationAttestation::new(
            order.work_order_id,
            [30u8; 32],
            receipt.evidence_manifest_hash,
            order.settlement.verifier,
            VerificationStatus::Rejected,
            5_000,
            1_100,
        );

        assert!(!invalid.is_valid_for(&order, &receipt));

        let valid = VerificationAttestation::new(
            order.work_order_id,
            [30u8; 32],
            receipt.evidence_manifest_hash,
            order.settlement.verifier,
            VerificationStatus::Rejected,
            0,
            1_100,
        );

        assert!(valid.is_valid_for(&order, &receipt));
    }

    #[test]
    fn completion_above_100_percent_is_rejected() {
        let order = work_order();
        let receipt = receipt(&order);

        let attestation = VerificationAttestation::new(
            order.work_order_id,
            [30u8; 32],
            receipt.evidence_manifest_hash,
            order.settlement.verifier,
            VerificationStatus::Accepted,
            10_001,
            1_100,
        );

        assert!(!attestation.is_valid_for(&order, &receipt));
    }

    #[test]
    fn evidence_hash_mismatch_is_rejected() {
        let order = work_order();
        let receipt = receipt(&order);

        let attestation = VerificationAttestation::new(
            order.work_order_id,
            [30u8; 32],
            [99u8; 32],
            order.settlement.verifier,
            VerificationStatus::Accepted,
            10_000,
            1_100,
        );

        assert!(!attestation.is_valid_for(&order, &receipt));
    }
}
